messages.content:
Tool response:
Tool: update_package_status
Description: Update Package Status
Parameters:
    {
      "type": "object",
      "properties": {
        "tracking_number": {
          "type": "string",
          "description": "The tracking number of the package to update",
          "title": "Tracking Number"
        },
        "status": {
          "type": "string",
          "title": "Status",
          "description": "The new status of the package (e.g., 'in transit')"
        },
        "scanned_at": {
          "type": "string",
          "title": "Scanned At",
          "description": "Timestamp when the package was scanned in ISO 8601 format"
        },
        "carrier_code": {
          "type": "string",
          "title": "Carrier Code",
          "description": "The carrier code associated with the package (e.g., 'UPS')"
        }
      },
      "required": [
        "tracking_number",
        "status",
        "scanned_at",
        "carrier_code"
      ]
    }
